package com.ajay.amusezone.controller;
import com.ajay.amusezone.entity.Offer; import com.ajay.amusezone.repository.OfferRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/offers") public class OfferController {private final OfferRepository r; public OfferController(OfferRepository r){this.r=r;} @GetMapping public List<Offer> all(){return r.findAll();} @GetMapping("/{code}") public Offer get(@PathVariable String code){return r.findByCodeIgnoreCase(code).orElseThrow(()->new RuntimeException("Offer not found"));} @PostMapping public Offer create(@RequestBody Offer x){return r.save(x);} @PutMapping("/{id}") public Offer update(@PathVariable Long id,@RequestBody Offer x){x.setId(id);return r.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){r.deleteById(id);}}
